package com.voicetxt.reader;
import android.app.Instrumentation;import android.os.Bundle;import java.io.*;import java.nio.charset.StandardCharsets;
public class ChapterInspectTest extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();} public void onStart(){Bundle result=new Bundle();try{StringBuilder report=new StringBuilder();for(String name:getTargetContext().fileList()){if(!name.endsWith(".txt"))continue;String value;try(InputStream in=getTargetContext().openFileInput(name)){value=new String(MainActivity.readBytes(in),StandardCharsets.UTF_8);}report.append("FILE ").append(name).append("\nHEAD\n").append(value.substring(0,Math.min(1500,value.length()))).append("\nPARSED\n");int count=0;for(MainActivity.Chapter c:MainActivity.parse(value)){if(count++>=5)break;report.append(c.name).append(" [").append(c.start).append(',').append(c.end).append("]\n").append(value.substring(c.start,Math.min(c.end,c.start+500))).append("\n---\n");}}try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"chapter-inspect.txt"))){out.write(report.toString().getBytes(StandardCharsets.UTF_8));}result.putString("result","saved");finish(-1,result);}catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));finish(0,result);}}
}
